-- Coach Zone — official exercise library seed
-- Run AFTER migrations. Official (library) exercises have author_id = NULL.
-- Descriptions and steps are in Polish (target
-- users are Polish-speaking coaches); category and sport names are
-- bilingual (name_pl / name_en).
--
-- This file is a full snapshot of the current official library: every
-- exercises row with author_id null, plus the complete positions and
-- exercise_positions tables. It replaces the previous, narrower version of
-- this file - the American football exercises added straight to
-- production by hand (never captured as a migration or a seed file) are
-- included here because this snapshot was generated by reading the live
-- tables directly, not by reconstructing history from
-- supabase_migrations.schema_migrations.
--
-- Idempotent / safe to re-run: every insert below is guarded (ON CONFLICT
-- or WHERE NOT EXISTS, keyed on the natural key - slug, or title for
-- exercises) so re-running this file against a database that already has
-- some or all of these rows is a no-op for the rows that already exist.
--
-- sport_id and category_id are always resolved by joining on sports.slug /
-- categories.slug - never hardcoded as a literal integer id. A hardcoded
-- id is exactly what caused a real production bug where soccer drills got
-- tagged as American football (see
-- 20260716100000_backfill_af_exercises.sql and its fix in
-- 20260727210405_exercise_scope_positions_and_sport_fix.sql). sport_id is
-- nullable: null means the exercise is universal and applies to every
-- discipline (six rows below, under UNIVERSAL). Nine rows are genuinely
-- football (soccer) rather than American football - both sports coexist
-- in this same official library, and that split is correct, not drift.
--
-- board_state and board_field_mode are carried over byte-for-byte from the
-- source data (board_state as Postgres's own compact jsonb text form) and
-- must not be reformatted, reindented, or pretty-printed.

insert into public.categories (slug, name_pl, name_en) values
  ('warmup',      'Rozgrzewka',        'Warm-up'),
  ('technical',   'Technika',          'Technical'),
  ('positional',  'Gra pozycyjna',     'Positional play'),
  ('ssg',         'Gry zadaniowe',     'Small-sided games'),
  ('strength',    'Motoryka',          'Strength & conditioning'),
  ('cooldown',    'Schłodzenie',       'Cool-down')
on conflict (slug) do nothing;

-- ============================================================================
-- Exercises - full official library (author_id is always null).
-- category_slug/sport_slug below are resolved to
-- category_id/sport_id via the joins in the insert; sport_slug null stays
-- null through the left join (universal exercise).
-- ============================================================================
with lib (category_slug, sport_slug, title, description, steps, duration_min,
          difficulty, equipment, media_url, board_state, board_field_mode) as (
  values
-- ============================================================================
