-- ============================================================================
-- ROZGRZEWKA (2)
('warmup', null, 'Aktywacja z drabinką koordynacyjną', 'Pobudzenie układu nerwowo-mięśniowego: szybka praca stóp i koordynacja przed częścią główną.', '{"5 wzorców kroków przez drabinkę (np. jedna stopa w polu, dwie stopy, bieg bokiem)","Po wyjściu z drabinki 5 m przyspieszenia","2–3 serie na wzorzec","Powrót truchtem do kolejki"}'::text[], 8, 1, '{"drabinka koordynacyjna"}'::text[], null, null::jsonb, null),
('warmup', null, 'Rozgrzewka dynamiczna w truchcie', 'Ogólna aktywacja przed treningiem: stopniowe podniesienie tętna i mobilizacja stawów w ruchu, bez statycznego rozciągania.', '{"Trucht wzdłuż linii boiska (2 okrążenia)","Wymachy nóg w przód i w bok co 10 m","Skip A, skip C, wielokroki","Krążenia bioder i obręczy barkowej","Kilka przyspieszeń na 70% na dystansie 20 m"}'::text[], 12, 1, '{pachołki}'::text[], null, null::jsonb, null),

-- MOTORYKA (2)
('strength', null, 'Interwały biegowe wysokiej intensywności', 'Rozwój wytrzymałości szybkościowej: powtarzane wysiłki blisko maksymalnego tempa.', '{"Wyznacz odcinek 40 m","15 s bieg na 90–95%, 45 s trucht/marsz powrotny","6–8 powtórzeń w serii","2 serie z 3 min przerwy między nimi","Kontroluj technikę biegu przy zmęczeniu"}'::text[], 18, 4, '{pachołki,stoper}'::text[], null, null::jsonb, null),
('strength', null, 'Obwód siłowy z masą własnego ciała', 'Wzmocnienie ogólne i profilaktyka urazów bez sprzętu — do wykonania na boisku.', '{"5 stacji: przysiady, wykroki, deska, pompki, mostek biodrowy","40 s pracy / 20 s przerwy na stację","Po pełnym obwodzie 2 min przerwy","2–3 rundy zależnie od okresu przygotowań","Akcent na poprawną technikę, nie liczbę powtórzeń"}'::text[], 15, 3, '{"maty (opcjonalnie)"}'::text[], null, null::jsonb, null),

-- SCHŁODZENIE (2)
('cooldown', null, 'Rolowanie i mobilizacja', 'Regeneracja powięziowa i redukcja napięcia mięśniowego po intensywnym treningu.', '{"Rolowanie: łydki, uda, pośladki, pasmo biodrowo-piszczelowe","30–45 s na każdą partię, unikaj rolowania stawów","Delikatna mobilizacja bioder i kręgosłupa piersiowego","Zakończ kilkoma spokojnymi, pełnymi oddechami"}'::text[], 10, 1, '{rollery}'::text[], null, null::jsonb, null),
('cooldown', null, 'Trucht wytłumiający i rozciąganie statyczne', 'Stopniowe obniżenie tętna i rozciąganie głównych grup mięśniowych po wysiłku.', '{"5 min spokojnego truchtu, przechodzącego w marsz","Rozciąganie statyczne: łydki, uda przednie i tylne, biodra","Każda pozycja utrzymywana 20–30 s","Spokojny, głęboki oddech przez cały czas"}'::text[], 10, 1, '{}'::text[], null, null::jsonb, null),

