-- ROZGRZEWKA (1)
('warmup', 'football', 'Rondo 4v1', 'Klasyczne dziadki: utrzymanie piłki w kole, aktywacja techniczna i pierwszy kontakt pod presją. Świetne na rozgrzewkę z piłką.', '{"4 zawodników na obwodzie koła (śr. 8–10 m), 1 w środku","Podania pierwszym kontaktem, maksymalnie dwa kontakty","Zawodnik ze środka odbiera lub wymusza stratę","Kto stracił lub podał źle — wchodzi do środka","Zmiana broniącego co 2 min"}'::text[], 10, 2, '{piłki,znaczniki}'::text[], null, null::jsonb, null),

-- TECHNIKA (3)
('technical', 'football', 'Podania w parach na dwa kontakty', 'Doskonalenie jakości pierwszego kontaktu i celności podania na krótkim dystansie.', '{"Pary naprzeciw siebie w odległości 8–12 m","Przyjęcie kierunkowe pierwszym kontaktem, podanie drugim","Po 10 podań zmiana nogi przyjmującej","Zwiększaj dystans i tempo z każdą serią"}'::text[], 12, 2, '{piłki,pachołki}'::text[], null, null::jsonb, null),
('technical', 'football', 'Prowadzenie piłki w slalomie', 'Kontrola piłki przy zmianach kierunku i praca obu nóg podczas prowadzenia.', '{"Ustaw 6 pachołków co 1,5 m","Prowadź piłkę slalomem wewnętrzną i zewnętrzną częścią stopy","Na końcu tor wykończ podaniem do partnera","Mierz czas, ale nie kosztem kontroli"}'::text[], 10, 2, '{piłki,pachołki}'::text[], null, null::jsonb, null),
('technical', 'football', 'Uderzenia na bramkę po podaniu', 'Wykończenie akcji: przyjęcie w ruchu i celne uderzenie z pierwszej lub po jednym kontakcie.', '{"Podający zagrywa z boku pola karnego","Strzelec nabiega, przyjmuje kierunkowo i uderza","Naprzemiennie prawa i lewa strona","Bramkarz w bramce — realna presja","Rotacja: strzelec → podający → koniec kolejki"}'::text[], 15, 3, '{piłki,bramka}'::text[], null, null::jsonb, null),

-- GRA POZYCYJNA (3)
('positional', 'football', 'Gra pozycyjna 6v6+3', 'Utrzymanie piłki z przewagą liczebną i nauka zajmowania właściwych pozycji w strefach.', '{"Kwadrat 25x25 m podzielony na strefy","6v6, 3 zawodników neutralnych zawsze z posiadającą drużyną","Cel: 8 podań pod rząd = punkt","Neutralni maksymalnie dwa kontakty","Akcent na szerokość i głębokość ustawienia"}'::text[], 18, 3, '{piłki,znaczniki,"znaczniki treningowe"}'::text[], null, null::jsonb, null),
('positional', 'football', 'Przejście z obrony do ataku (tranzycja)', 'Szybkie przejście do ataku po odbiorze i natychmiastowy powrót do obrony po stracie.', '{"Dwie drużyny 7v7 na połowie boiska","Po odbiorze drużyna ma 8 s na dojście do bramki","Po stracie natychmiastowy pressing (5 s)","Trener wrzuca nową piłkę po każdej akcji, by utrzymać tempo"}'::text[], 20, 4, '{piłki,bramki,znaczniki}'::text[], null, null::jsonb, null),
('positional', 'football', 'Wyprowadzenie piłki spod pressingu 4v2', 'Budowanie gry od tyłu: cierpliwe wyprowadzenie przez linie mimo presji dwóch napastników.', '{"4 obrońców/pomocników w prostokącie, 2 napastników presuje","Zadanie: przeprowadzić piłkę przez linię końcową podaniem","Napastnicy po odbiorze strzelają do małej bramki","Zmiana ról co 3 min"}'::text[], 15, 3, '{piłki,"małe bramki",znaczniki}'::text[], null, null::jsonb, null),

-- GRY ZADANIOWE (2)
('ssg', 'football', 'Gra 4v4 na cztery bramki', 'Mała gra rozwijająca zmianę kierunku ataku i orientację w przestrzeni.', '{"Boisko 30x20 m, po dwie małe bramki na każdej połowie szerokości","Można zdobyć gola w dowolną z dwóch bramek przeciwnika","Zachęcaj do szybkiej zmiany strony ataku","4–6 minut na serię, przerwa na wodę"}'::text[], 16, 3, '{piłki,"małe bramki",znaczniki}'::text[], null, null::jsonb, null),
('ssg', 'football', 'Gra 7v7 z warunkiem dwóch kontaktów', 'Gra właściwa z ograniczeniem liczby kontaktów — wymusza szybkie myślenie i grę bez piłki.', '{"Boisko ok. 50x40 m, bramki z bramkarzami","Maksymalnie dwa kontakty na zawodnika","Trzeci kontakt = rzut wolny dla przeciwnika","Znieś warunek na ostatnie 5 min dla swobodnej gry"}'::text[], 20, 3, '{piłki,bramki,znaczniki}'::text[], null, null::jsonb, null),

