-- ROZGRZEWKA (5)
('warmup', 'american_football', 'Agility z płotkami', 'Praca nóg przez rząd płotków — częstotliwość kroku i wysokie kolano.', '{"Ustawiamy rząd płotków w równych odstępach","WR przechodzi przez płotki, pracując nad częstotliwością kroku","Kończymy sprintem za ostatnim płotkiem","Warianty: przód, bokiem, obunóż"}'::text[], 8, 2, '{płotki}'::text[], null, '[{"x": 124, "y": 352, "id": "z1", "kind": "player", "type": "point", "label": "WR"}, {"id": "z2", "kind": "hurdles", "type": "path", "color": "#dc2626", "curved": false, "points": [{"x": 164, "y": 352}, {"x": 268, "y": 352}], "headStyle": "none", "strokeWidth": 3}, {"id": "z3", "kind": "route", "type": "path", "color": "#111827", "curved": false, "points": [{"x": 138, "y": 352}, {"x": 164, "y": 352}, {"x": 268, "y": 352}, {"x": 322, "y": 352}], "headStyle": "arrow", "strokeWidth": 4}]'::jsonb, 'redzone'),
('warmup', 'american_football', 'Ball drills', 'Zestaw ćwiczeń czucia piłki dla WR — do rozgrzewki lub jako uzupełnienie.', '{"Podrzucanie i łapanie piłki jedną ręką trzymając ją od góry","Naprzemienne łapanie piłki za koniec","Przekładanie piłki dookoła ciała","Przekładanie piłki dookoła nogi","Przekładanie piłki pomiędzy nogami","Upuszczanie piłki z wierzchu dłoni i łapanie za koniec"}'::text[], 8, 1, '{piłka}'::text[], null, null::jsonb, null),
('warmup', 'american_football', 'Cardio', 'Blok kondycyjny na start treningu — przeskoki, sprinty ze zmianą kierunku i praca w podporze.', '{"Przeskoki obunóż: przód - bok - przód - bok - przód","Sprinty z okrążaniem znaczników, twarzą w kierunku sprintu","Niedźwiedzie — marsz na czworaka","W-drill: sprint - backpedal"}'::text[], 10, 2, '{pachołki}'::text[], null, null::jsonb, null),
('warmup', 'american_football', 'Kwadrat', 'Praca nóg OL po obwodzie kwadratu — powolna, kontrolowana, nisko na nogach.', '{"Ustawiamy kwadrat 5y x 5y","OL startuje z pozycji, powoli i nisko na nogach","Do przodu -> sidestep -> backpedal -> sidestep"}'::text[], 8, 1, '{pachołki}'::text[], null, null::jsonb, null),
('warmup', 'american_football', 'Wyścigi', 'Rozgrzewkowa rywalizacja z transportem piłki — cztery warianty podania.', '{"Dzielimy się na 2 rzędy, każdy rozstawia się wzdłuż boiska co 10y","Cel: przetransportować piłkę w jedną i w drugą stronę","Gdy piłka wróci do pierwszego zawodnika, cały rząd musi dobiec do niego i go dotknąć","Warianty transportu: zwykły rzut / rzut słabszą ręką / toss bokiem / long snap","Przegrana drużyna robi 10 pompek"}'::text[], 15, 1, '{piłka}'::text[], null, null::jsonb, null),

-- TECHNIKA (51)
('technical', 'american_football', '1 on 1 covered catch', 'WR i DB pracują razem: WR łapie pod kryciem, DB uczy się zbijać bez obracania się do piłki. W planach treningowych występuje też pod nazwą "fade adjustment".', '{"WR ustawia się w pozycji, zaraz za nim staje DB","5-10y za nimi staje QB","Na sygnał WR i DB ruszają przed siebie","QB rzuca piłkę — może lekko na lewo lub prawo, żeby WR musiał się dostosować","DB obserwuje WR i stara się włożyć rękę między jego dłonie","DB nie może obracać się do piłki — czyta jej lot z ruchu WR"}'::text[], 10, 4, '{piłka}'::text[], null, null::jsonb, null),
('technical', 'american_football', '1 on 1 pass pro', 'Rywalizacja OL kontra DL w pass protection — jeden na jednego.', '{"OL ustawia się w pozycji, DL naprzeciwko","Na sygnał DL rusza do rushu, OL broni","Ustalamy limit czasu (np. 3 sekundy) jako sukces OL","Rotujemy zawodników po każdym powtórzeniu"}'::text[], 10, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', '1 on 1 routes', 'Rywalizacja WR kontra DB — ścieżka przeciwko kryciu, jeden na jednego.', '{"WR ustawia się na linii, DB naprzeciwko","QB rzuca do WR","WR biega wybraną ścieżkę, DB stara się ją pokryć","Rotujemy zawodników po każdym powtórzeniu"}'::text[], 10, 3, '{piłka}'::text[], null, null::jsonb, null),
('technical', 'american_football', '1 on 1 run', 'Rywalizacja OL kontra DL w blokach biegowych — jeden na jednego.', '{"OL ustawia się w pozycji, DL naprzeciwko","Ustalamy kierunek biegu (inside/outside)","Na sygnał OL wykonuje blok, DL stara się utrzymać gap","Rotujemy zawodników po każdym powtórzeniu"}'::text[], 10, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Backpedal + cut + fly', 'DB łączy backpedal, ścięcie i obrót w bieg w głąb boiska zakończony zbiciem lub złapaniem piłki.', E'{"DB startuje w pozycji","Na ruch partnera \\"QB\\" zaczyna backpedal","Ścina do cuta","Przy następnym znaczniku obraca się i biegnie w głąb boiska","Zbija lub łapie piłkę"}'::text[], 10, 3, '{piłka,pachołki}'::text[], null, '[{"x": 176, "y": 416, "id": "j1", "kind": "opponent", "type": "point", "label": "DB"}, {"x": 126, "y": 444, "id": "j2", "kind": "qb", "type": "point", "label": "QB"}, {"x": 176, "y": 356, "id": "j3", "kind": "cone", "type": "point", "label": ""}, {"x": 232, "y": 352, "id": "j4", "kind": "cone", "type": "point", "label": ""}, {"id": "j5", "kind": "route", "type": "path", "color": "#111827", "curved": false, "points": [{"x": 176, "y": 404}, {"x": 176, "y": 370}, {"x": 226, "y": 364}, {"x": 262, "y": 300}, {"x": 278, "y": 268}], "headStyle": "arrow", "strokeWidth": 4}, {"id": "j6", "dash": [14, 10], "kind": "passLine", "type": "path", "color": "#7c3aed", "curved": false, "points": [{"x": 138, "y": 438}, {"x": 270, "y": 278}], "headStyle": "arrow", "strokeWidth": 4}]'::jsonb, 'redzone'),
('technical', 'american_football', 'Ball strip', 'Dwóch obrońców: pierwszy zatrzymuje, drugi wyszarpuje piłkę.', E'{"Ustawiamy dwa rzędy, naprzeciwko nich staje \\"RB\\" z piłką","Na sygnał \\"RB\\" rusza truchtem w stronę jednego z rzędów","Defensorzy biegną do niego","Pierwszy schodzi nisko do tackla i obejmuje \\"RB\\" — bez tackla do ziemi","Drugi dobiega i wyszarpuje piłkę"}'::text[], 10, 3, '{piłka}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Block shed + tackle', 'Obrońca wchodzi w kontakt z blokującym, czyta biegacza, zrzuca blok i tackluje. Ćwiczenie łączy pracę rąk z reakcją na kierunek biegu.', '{"Zawodnik ustawia się naprzeciw blokującego","5y za plecami blokującego ustawia się RB","Na sygnał zawodnik wchodzi w kontakt z blokującym i obserwuje RB","RB rusza po skosie w wybraną przez siebie stronę","Zawodnik zrzuca blok i tackluje biegacza"}'::text[], 10, 3, '{}'::text[], null, '[{"x": 192, "y": 200, "id": "a1", "kind": "player", "type": "point", "label": "RB"}, {"x": 192, "y": 265, "id": "a2", "kind": "player", "type": "point", "label": "OL"}, {"x": 192, "y": 320, "id": "a3", "kind": "opponent", "type": "point", "label": "D"}, {"x": 105, "y": 392, "id": "a4", "kind": "cone", "type": "point", "label": ""}, {"x": 279, "y": 392, "id": "a5", "kind": "cone", "type": "point", "label": ""}, {"id": "a6", "kind": "block", "type": "path", "color": "#b91c1c", "curved": false, "points": [{"x": 192, "y": 282}, {"x": 192, "y": 304}], "headStyle": "bar", "strokeWidth": 5}, {"id": "a7", "kind": "route", "type": "path", "color": "#111827", "curved": false, "points": [{"x": 192, "y": 218}, {"x": 170, "y": 270}, {"x": 120, "y": 378}], "headStyle": "arrow", "strokeWidth": 4}, {"id": "a8", "dash": [14, 10], "kind": "route", "type": "path", "color": "#111827", "curved": false, "points": [{"x": 192, "y": 218}, {"x": 214, "y": 270}, {"x": 264, "y": 378}], "headStyle": "arrow", "strokeWidth": 4}, {"id": "a9", "kind": "route", "type": "path", "color": "#111827", "curved": false, "points": [{"x": 178, "y": 322}, {"x": 146, "y": 354}, {"x": 128, "y": 370}], "headStyle": "arrow", "strokeWidth": 4}]'::jsonb, 'redzone'),
('technical', 'american_football', 'Bull rush', 'Rush siłowy — przepchnięcie blokującego i zrzucenie bloku w gap.', E'{"DL startuje z pozycji naprzeciw partnera \\"OL\\"","Na ruch \\"OL\\" (kick step) rusza","Wchodzi z nim w kontakt obiema rękoma","Przepycha go 3y do tyłu i zrzuca blok, wskakując w gap biodrami","Kończy sprintem 5y za partnera"}'::text[], 10, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Fly man cover', 'Krycie man z off — read step i otwarcie bioder.', E'{"DB ustawia się w off man","\\"WR\\" startuje biegnąc fade lub seam — release w prawo lub w lewo, potem prosto po wybranej stronie DB","DB rusza backpedalem, robiąc read step w stronę release","Gdy \\"WR\\" zaczyna go mijać, otwiera biodra w jego stronę i biegnie z nim"}'::text[], 10, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Forklift', 'Wypchnięcie rąk blokującego w górę i wejście za jego plecy.', E'{"W parach, partner \\"OL\\" kładzie wyciągnięte ręce na klatce DL","Na sygnał zaczyna go lekko pchać","DL łapie obiema rękoma przedramiona \\"OL\\" i wypycha jego ręce w górę","Następnie wchodzi za jego plecy"}'::text[], 8, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Goalline tackle', 'Tackle na krótkim dystansie z wyborem strony. Nacisk na niski kontakt.', '{"Zawodnik O# ustawia się nad leżącą piłką","Zawodnik D# staje 2y od niego, pomiędzy dwoma znacznikami","Na sygnał O# podnosi piłkę i kieruje się na jeden ze znaczników","D# tackluje go","Pracować nad niskim tacklem — celujemy w biodro, a nie w barki"}'::text[], 10, 4, '{piłka,pachołki}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Handoffs', 'Podstawa wymiany piłki QB-RB, z zaznaczonym punktem celowania.', '{"RB pracuje z QB","Handoff do inside i outside","QB co jakiś czas wyciąga piłkę (mesh read)","Ustawić ze znaczników miejsce, w które celuje RB — wewnętrzne biodro guarda lub na zewnątrz TE"}'::text[], 10, 2, '{piłka,pachołki}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Hands fight', 'Walka rąk zakończona przejściem za plecy blokującego.', E'{"W parach, partner \\"OL\\" stara się położyć ręce na klatce DL","DL zbija je, \\"OL\\" szybko wraca rękoma na klatkę","Po ok. 5s zbijania rąk DL uzupełnia ruch o przejście za plecy \\"OL\\""}'::text[], 8, 3, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Hands replace', 'Szybkość powrotu rąk na pady. Praca nad tym, żeby zbity blok nie oznaczał końca akcji.', '{"W parach, OL stoi nisko na nogach","OL kładzie ręce na klatce partnera","Partner zbija mu ręce — pojedynczo lub obie naraz","OL jak najszybciej wraca dłonią na pady"}'::text[], 8, 2, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Hips roll', 'Praca bioder w kontakcie — wyciągnięcie przeciwnika w górę zamiast pchania na wprost.', E'{"W parach, DL łapie partnera \\"OL\\" za pady","Staje nisko, wychylony do przodu","Na sygnał pcha partnera","Równocześnie wyciąga go w górę, przybliżając do niego biodra"}'::text[], 8, 2, '{}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'Hitch / comeback', 'Dwie ścieżki na krótkim dystansie — nacisk na sprzedanie dalekiej ścieżki.', '{"Biegamy standardowy hitch (5y) i comeback (7y)","Mocny start","Sprzedanie dalekiej ścieżki","Dynamiczne ścięcie"}'::text[], 10, 2, '{piłka}'::text[], null, null::jsonb, null),
('technical', 'american_football', 'IZ course', 'Tor biegowy RB: start jak do inside zone, handoff, cutback na znaczniku, stiff arm na tarczy i spin na kolejnym znaczniku.', '{"Biegacz zaczyna z pozycji","Na sygnał startuje jak do Inside Zone i odbiera handoff","Na znaczniku ścina w przeciwną stronę (cutback)","Robi stiff arm, obiegając partnera z tarczą","Dobiegając do znacznika, robi spin w przeciwną stronę"}'::text[], 10, 3, '{piłka,tarcza,pachołki}'::text[], null, '[{"x": 128, "y": 298, "id": "c1", "kind": "qb", "type": "point", "label": "QB"}, {"x": 128, "y": 350, "id": "c2", "kind": "player", "type": "point", "label": "RB"}, {"x": 196, "y": 296, "id": "c3", "kind": "cone", "type": "point", "label": ""}, {"x": 252, "y": 338, "id": "c4", "kind": "shield", "type": "point", "label": ""}, {"x": 314, "y": 296, "id": "c5", "kind": "cone", "type": "point", "label": ""}, {"id": "c6", "kind": "route", "type": "path", "color": "#111827", "curved": true, "points": [{"x": 144, "y": 348}, {"x": 178, "y": 322}, {"x": 194, "y": 312}, {"x": 210, "y": 338}, {"x": 234, "y": 372}, {"x": 268, "y": 370}, {"x": 296, "y": 320}, {"x": 304, "y": 306}], "headStyle": "arrow", "strokeWidth": 4}]'::jsonb, 'redzone'),
