)
insert into public.exercises
  (author_id, sport_id, category_id, title, description, steps, duration_min,
   difficulty, equipment, media_url, is_public, board_state, board_field_mode)
select
  null, sp.id, c.id, l.title, l.description, l.steps, l.duration_min,
  l.difficulty, l.equipment, l.media_url, true, l.board_state, l.board_field_mode
from lib l
join public.categories c on c.slug = l.category_slug
left join public.sports sp on sp.slug = l.sport_slug
where not exists (
  select 1 from public.exercises e
  where e.title = l.title and e.author_id is null
);

-- ============================================================================
-- Positions catalog - American football only today. sport_id is resolved
-- from sports.slug via v_af, never hardcoded.
-- ============================================================================
do $$
declare
  v_af int;
begin
  select id into v_af from public.sports where slug = 'american_football';
  if v_af is null then
    raise exception 'Nie znaleziono sportu o slugu "american_football".';
  end if;

  insert into public.positions (sport_id, code, label, sort_order) values
    (v_af, 'OL',   'Linia ofensywna (OL)',   10),
    (v_af, 'QB',   'Rozgrywający (QB)',      20),
    (v_af, 'RB',   'Biegacz (RB)',           30),
    (v_af, 'WR',   'Skrzydłowy (WR)',        40),
    (v_af, 'TE',   'Tight end (TE)',         50),
    (v_af, 'DL',   'Linia defensywna (DL)',  60),
    (v_af, 'DE',   'Defensive end (DE)',     70),
    (v_af, 'LB',   'Linebacker (LB)',        80),
    (v_af, 'DB',   'Defensive back (DB)',    90),
    (v_af, 'TEAM', 'Cała drużyna',          100)
  on conflict (sport_id, code) do nothing;
end $$;

