insert into public.exercise_positions (exercise_id, position_id)
select e.id, p.id
from links l
cross join af
join public.exercises e on e.title = l.title and e.author_id is null
join public.positions p on p.sport_id = af.id and p.code = l.code
on conflict do nothing;
